# ---------------------------------------------------------------- 文本归一化
def norm_text(s):
    """NFKC + 小写 + 非字母数字/汉字压成单空格。"""
    s = unicodedata.normalize("NFKC", s or "").lower()
    s = re.sub(r"[^0-9a-z一-鿿]+", " ", s)
    return " ".join(s.split())


def norm_key(s):
    """去掉一切非字母数字/汉字（用于 DOI 后缀包含判断）。"""
    s = unicodedata.normalize("NFKC", s or "").lower()
    return re.sub(r"[^0-9a-z一-鿿]+", "", s)


def tokens(s):
    """归一化后的词集合；单字符词（多为噪声）剔除。"""
    return {t for t in norm_text(s).split() if len(t) > 1}


def coverage(needle, haystack):
    """needle 的 token 有多少比例出现在 haystack 中。"""
    a, b = tokens(needle), tokens(haystack)
    if not a:
        return 0.0
    return len(a & b) / len(a)


def title_variants(stem):
    """完整标题型文件名可能带 ` - 期刊 - 年` 后缀，逐级剥。"""
    out = [stem]
    parts = stem.split(" - ")
    for n in range(len(parts) - 1, 0, -1):
        out.append(" - ".join(parts[:n]))
    return out


# ---------------------------------------------------------------- 文件读取
def read_frontmatter(path):
    text = K.read_text(path)
    fm_raw, _ = K.split_frontmatter(text)
    if not fm_raw:
        return {}
    try:
        fm = yaml.safe_load(fm_raw)
    except yaml.YAMLError:
        return {}
    return fm if isinstance(fm, dict) else {}


def _looks_like_title(s):
    """排除 ACS/Wiley 常见的「文件名 + 页码范围」式元数据标题。"""
    s = (s or "").strip()
    if len(s) < 15 or s.lower().endswith(".pdf"):
        return False
    if re.match(r"^[a-z0-9._-]+\s+\d+\s*\.\.\s*\d+$", s, re.I):
        return False
    return True


def pdf_title_text(path):
    """PDF 标题文本：优先元数据 title，退化到首页前 600 字符。

    🔴 不要用前两页全文做覆盖率匹配——正文/参考文献里会凑齐任意标题的词，
    2026-10-23 实测把 Chem. Rev. 综述误配到膜综述卡上（4 例假阳性）。
    """
    try:
        import fitz  # PyMuPDF
    except Exception:
        return ""
    try:
        doc = fitz.open(path)
        try:
            meta = (doc.metadata or {}).get("title") or ""
            if _looks_like_title(meta):
                return meta
            if len(doc) == 0:
                return ""
            return (doc[0].get_text("text") or "")[:600]
        finally:
            doc.close()
    except Exception:
        return ""


def docx_text(path, limit=20000):
    """docx 正文纯文本（只读 word/document.xml）。失败返回空串。"""
    try:
        with zipfile.ZipFile(path) as z:
            xml = z.read("word/document.xml").decode("utf-8", errors="ignore")
    except Exception:
        return ""
    xml = re.sub(r"<w:p[ >]", "\n<w:p ", xml)
    text = re.sub(r"<[^>]+>", " ", xml)
    return re.sub(r"\s+", " ", text)[:limit]


# ---------------------------------------------------------------- 卡与文件
class Card(object):
    def __init__(self, stem, fm, ext_title, h1=""):
        self.stem = stem
        self.fm = fm
        self.ext_title = ext_title or stem
        self.h1 = h1 or ""
        self.doi = str(fm.get("doi") or "")
        self.si_status = str(fm.get("si_status") or "")
        si = fm.get("si_file")
        if isinstance(si, str):
            self.si_files = [si]
        elif isinstance(si, list):
            self.si_files = [str(x) for x in si]
        else:
            self.si_files = []

    def titles(self):
        """可用于匹配的全标题：Extract 文件名 + 正文 H1（去重）。"""
        out = []
        for t in (self.ext_title, self.h1):
            if t and t not in out:
                out.append(t)
        return out


def load_cards(project):
    src = os.path.join(project, "sources")
    cards = []
    for path in sorted(glob.glob(os.path.join(src, "*.md"))):
        stem = os.path.splitext(os.path.basename(path))[0]
        if stem == "index":
            continue
        text = K.read_text(path)
        fm_raw, body = K.split_frontmatter(text)
        try:
            fm = yaml.safe_load(fm_raw) if fm_raw else {}
        except yaml.YAMLError:
            fm = {}
        if not isinstance(fm, dict) or not fm:
            continue
        ext_title = ""
        for link in (fm.get("sources") or []):
            m = re.search(r"Extract/(.+)\.md\]\]", str(link))
            if m:
                ext_title = m.group(1)
                break
        h1 = ""
        for line in body.split("\n"):
            if line.startswith("# "):
                h1 = line[2:].strip()
                break
        cards.append(Card(stem, fm, ext_title, h1))
    return cards


def list_files(directory, exts=None):
    if not os.path.isdir(directory):
        return []
    out = []
    for name in sorted(os.listdir(directory)):
        path = os.path.join(directory, name)
        if not os.path.isfile(path):
            continue
        if exts and os.path.splitext(name)[1].lower() not in exts:
            continue
        out.append(name)
    return out


def doi_suffix(doi):
    """DOI 后缀（最后一段），归一化后用于文件名包含判断。"""
    tail = (doi or "").rsplit("/", 1)[-1]
    key = norm_key(tail)
    return key if len(key) >= 6 else ""


def si_stem(filename):
    """SI 文件干；`<卡名>.si.pdf` 是卡名同干约定的一部分，剥掉 `.si`。"""
    stem = os.path.splitext(filename)[0]
    if stem.lower().endswith(".si"):
        stem = stem[:-3]
    return stem


def pii_prefix(filename):
    """Elsevier PII 或 Wiley 稿件号前缀；用于 mmc1/mmc2 这类同文多文件。"""
    m = re.search(r"(1-s2\.0-S\d{10,})", filename, re.I)
    if m:
        return m.group(1).lower()
    m = re.search(r"^([a-z]{2,6}\d{6,})[-_]", filename, re.I)
    if m:
        return m.group(1).lower()
    return ""


# ---------------------------------------------------------------- 匹配
def match_pdf(stem, cards, use_pdf_text=True):
    """返回 (card, method)。method ∈ stem/title/doi/tokens/first/unmatched。"""
    by_stem = {c.stem: c for c in cards}
    if stem in by_stem:
        return by_stem[stem], "stem"
    for variant in title_variants(stem):
        key = norm_text(variant)
        for c in cards:
            if any(norm_text(t) == key for t in c.titles()):
                return c, "title"
    name_key = norm_key(stem)
    for c in cards:
        suffix = doi_suffix(c.doi)
        if suffix and suffix in name_key:
            return c, "doi"
    for c in cards:
        if max((coverage(t, stem) for t in c.titles()), default=0.0) >= 0.85:
            return c, "tokens"
    return None, "unmatched"


def match_pdf_with_text(path, stem, cards):
    """文件名匹配失败时，回退到 PDF 首页文本。"""
    card, method = match_pdf(stem, cards, use_pdf_text=False)
    if card:
        return card, method
    text = pdf_title_text(path)
    if text:
        scored = sorted(
            ((max((coverage(t, text) for t in c.titles()), default=0.0), c) for c in cards),
            key=lambda x: x[0], reverse=True)
        best_cov, best_card = scored[0]
        second = scored[1][0] if len(scored) > 1 else 0.0
        # 门槛 + 领先第二名：避免「大家都像」时硬配一张
        if best_card is not None and best_cov >= 0.85 and best_cov - second >= 0.10:
            return best_card, "first"
    return None, "unmatched"


def audit(project, use_pdf_text=True):
    cards = load_cards(project)
    pdf_dir = os.path.join(project, PDF_DIR)
    ext_dir = os.path.join(project, EXT_DIR)
    si_dir = os.path.join(project, SI_DIR)

    pdf_files = list_files(pdf_dir, {".pdf"})
    ext_files = list_files(ext_dir, {".md"})
    si_files = list_files(si_dir)

    pdf_rows = {}
    for name in pdf_files:
        stem = os.path.splitext(name)[0]
        card, method = match_pdf_with_text(os.path.join(pdf_dir, name), stem, cards) \
            if use_pdf_text else match_pdf(stem, cards, False)
        pdf_rows[name] = (card.stem if card else None, method)

    ext_rows = {}
    for name in ext_files:
        stem = os.path.splitext(name)[0]
        card = next((c for c in cards if c.stem == stem), None)
        if card:
            ext_rows[name] = (card.stem, "stem")
            continue
        key = norm_text(stem)
        card = next((c for c in cards if norm_text(c.ext_title) == key), None)
        ext_rows[name] = (card.stem, "title") if card else (None, "unmatched")

    si_rows = {}
    claimed = {}
    for c in cards:
        for rel in c.si_files:
            claimed.setdefault(os.path.basename(rel), c.stem)
    pii_owner = {}
    for name, owner in claimed.items():
        p = pii_prefix(name)
        if p:
            pii_owner[p] = owner
    for name in si_files:
        card = next((c for c in cards if c.stem == si_stem(name)), None)
        if card:
            si_rows[name] = (card.stem, "stem")
            continue
        if name in claimed:
            si_rows[name] = (claimed[name], "si_file")
            continue
        p = pii_prefix(name)
        if p and p in pii_owner:
            si_rows[name] = (pii_owner[p], "pii")
            continue
        si_rows[name] = (None, "orphan")

    # 每张卡聚合
    rows = []
    for c in cards:
        pdfs = [n for n, (owner, _) in pdf_rows.items() if owner == c.stem]
        exts = [n for n, (owner, _) in ext_rows.items() if owner == c.stem]
        sis = [n for n, (owner, _) in si_rows.items() if owner == c.stem]
        rows.append({
            "card": c.stem,
            "pdf": pdfs,
            "extract": exts,
            "si": sis,
            "si_status": c.si_status,
            "doi": c.doi,
        })

    summary = {
        "cards": len(cards),
        "pdf_files": len(pdf_files),
        "extract_files": len(ext_files),
        "si_files": len(si_files),
        "pdf": _count_methods(pdf_rows),
        "extract": _count_methods(ext_rows),
        "si": _count_methods(si_rows),
        "unmatched_pdf": sorted(n for n, (o, _) in pdf_rows.items() if not o),
        "unmatched_extract": sorted(n for n, (o, _) in ext_rows.items() if not o),
        "orphan_si": sorted(n for n, (o, _) in si_rows.items() if not o),
        "cards_without_pdf": sorted(r["card"] for r in rows if not r["pdf"]),
        "cards_without_extract": sorted(r["card"] for r in rows if not r["extract"]),
    }
    detail = {
        "pdf": pdf_rows,
        "extract": ext_rows,
        "si": si_rows,
    }
    return rows, summary, detail


def _count_methods(rows):
    out = {}
    for _, method in rows.values():
        out[method] = out.get(method, 0) + 1
    return out


